// Self-contained so the downloadable page runs the same interface without
// embedding any roster, password, session token, or private portal data.
export function mountWelcome(root,options){
 const welcomeMascot="data:image/png;base64,";
 const home=options.alliance,tag=home==='NvEM'?'BaDa':home,admin=!!options.adminCall;
 const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const compact=v=>v==null?'—':Intl.NumberFormat('en',{notation:'compact',maximumFractionDigits:1}).format(Number(v));
 const instructions=[
  '1616 — '+tag+' Welcome desk',
  '1. Open your alliance’s Welcome link and enter the alliance password. Stay online while using the page.',
  '2. Add your R4s’ in-game names under R4 team, then click Save welcome settings. Choose your own name under Working as. This sets your default name; it does not claim every player.',
  '3. Edit the shared welcome message if needed. Keep the merge fields shown below the editor: {player}, {r4} and {alliance} fill in names automatically. Keep the message within 500 characters. Check Preview for, then click Save welcome settings. The message is shared by your alliance’s R4 team.',
  '4. Find an Available player and select your name under Contacted by. This claims that player and saves immediately. Avoid contacting someone already claimed by another R4; coordinate with them first.',
  '5. Click Copy welcome beside the player, then paste and send the message to that player in Last War. Copying does not send anything or change their contact status.',
  '6. Available = nobody is handling this player. Claimed = an R4 is handling contact or follow-up. Completed = you have sent the welcome and finished the necessary follow-up. Mark Completed when finished; this saves immediately. Choosing Available releases the claim.',
  '7. Open Team notes, choose your name under Note by, write any useful handoff or follow-up details, and click Save team note. Notes sync to the main portal with your R4 name and alliance. They are shared team notes, not private messages.',
  '8. Wait for a saved confirmation. If an error appears, your change may not have saved: check your connection and retry. Refresh loads the latest saved data; it asks before replacing unsaved message or R4-list edits.',
  'Only Approved or Accepted players assigned to '+tag+' appear here. Contact status does not change application status, seat colour, or destination alliance.',
  'No file needs to be sent back. Saved changes go directly to the portal. A downloaded page still needs internet and the alliance password. Keep the password within your authorized alliance leadership.'
 ].join('\n\n');
 const help={
  message:'Edit the shared welcome template, up to 500 characters. {player} is the player’s name, {r4} is Working as (or their contact owner), and {alliance} is your destination alliance. Check the personalized preview length, then Save welcome settings.',
  team:'Add each R4’s in-game name, then choose Save welcome settings. Saved names become available for player claims and note attribution. Removing a name does not erase previous claims or notes.',
  working:'Choose your own R4 name. It is the default for new notes and for claiming via Contact status. It does not automatically claim players or change existing claims.',
  owner:'Selecting an R4 claims this player and saves immediately. Choose Unassigned to release the claim. If another R4 has claimed the player, coordinate with them before taking over.',
  state:'Available: no one is handling contact. Claimed: an R4 is handling contact or follow-up. Completed: the welcome has been sent and follow-up is finished. Changes save immediately; Available releases the claim.',
  copy:'Copies a personalized welcome for this player. Paste and send it yourself in Last War. It does not send a message, claim the player, or mark contact completed.',
  notes:'Choose the R4 who wrote the note, then click Save team note. It syncs to the main portal with that R4’s name and alliance, even without a transfer-team account. Notes are shared, not private.',
  save:'Saves the shared welcome message and R4 names online. Wait for the saved confirmation. Contact dropdowns save immediately; each note needs its own Save team note button.',
  refresh:'Loads the latest saved roster, contact states, settings and notes. You will be asked before unsaved message or R4-list edits are replaced. Unsaved note drafts stay on this page.',
  download:'Downloads an HTML copy of this desk. It still requires internet and your alliance password, and saved changes go to the same database. You do not send the file back.',
  search:'Search by player name, source server, source alliance, transfer group, or contacting R4. Searching does not change any records.',
  filter:'Show all contacts, or only Available, Claimed, or Completed players. This filters outreach progress, not application approval.'
 };
 const helpButton=(key,label)=>'<button type="button" class="welcome-help-button" data-welcome-help="'+key+'" aria-label="Help: '+label+'" aria-expanded="false">?</button>';
 const defaultMessage="Hi {player}! My name is {r4}, and I'd love to welcome you to 1616! We'd be happy to have you join {alliance} for the season. Once you arrive on 1616, please apply to {alliance}. We're looking forward to welcoming you to the family!";
 const oldDefault='Hi {player}, welcome to {alliance}! We are happy to have you with us.';
 const r4For=p=>leaders.find(l=>l.id===selected)?.name||leaders.find(l=>l.id===p.outreach?.leaderId)?.name||p.outreach?.name||'';
 const messageFor=(message,p)=>{
  const values={player:p.name,r4:r4For(p)||'[R4 name]',alliance:tag,server:p.server||'—',seat:p.confirmedSeat||'unconfirmed'};
  const text=message.replace(/\{(player|r4|alliance|server|seat)\}/g,(_,key)=>values[key]);
  return message.includes('{player}')?text:'Hi '+p.name+',\n\n'+text;
 };
 let token='',page=null,draft='',leaders=[],dirty=false,busy=false,query='',filter='',selected='',refreshing=false,editorOpen='',noteDrafts=new Map(),openNotes=new Set();
 try{token=sessionStorage.getItem('welcome:'+home)||'';}catch{}
 const remember=()=>{try{token?sessionStorage.setItem('welcome:'+home,token):sessionStorage.removeItem('welcome:'+home);}catch{}};
 const call=async(action,body={})=>{
  if(admin)return options.adminCall('admin.'+action,{alliance:home,...body});
  let response;try{response=await fetch(options.endpoint,{method:'POST',credentials:'omit',headers:{'Content-Type':'application/json',apikey:options.key,...(token?{'X-Welcome-Session':token}:{})},body:JSON.stringify({action,alliance:home,...body}),signal:AbortSignal.timeout(30000)});}catch{throw Error('Not saved. Check your internet connection and try again.');}
  const result=await response.json();if(!response.ok||result.error){const error=Error(result.error||'The request could not be completed.');error.code=result.code;if(response.status===401){token='';remember();}throw error;}return result;
 };
 const status=(text,error=false)=>{const el=root.querySelector('[data-status]');if(el){el.textContent=text;el.dataset.error=String(error);}};
 const optionsFor=(value,empty='Choose R4…')=>'<option value="">'+empty+'</option>'+leaders.map(l=>'<option value="'+esc(l.id)+'" '+(l.id===value?'selected':'')+'>'+esc(l.name)+'</option>').join('');
 const copy=async(text,button,label='Copy welcome')=>{try{await navigator.clipboard.writeText(text);button.textContent=button.classList.contains('welcome-icon-button')?'✓':'Copied';setTimeout(()=>{if(button.isConnected)button.textContent=label;},1800);}catch{const d=document.createElement('dialog');d.innerHTML='<h3>'+esc(label)+'</h3><p>Select and copy this text.</p><textarea rows="10" readonly></textarea><button type="button">Close</button>';d.querySelector('textarea').value=text;root.append(d);d.querySelector('button').onclick=()=>{d.close();d.remove();};d.showModal();d.querySelector('textarea').select();}};
 let helpTarget=null,helpPinned=false,helpSerial=0,helpTimer;
 const hideHelp=()=>{clearTimeout(helpTimer);if(helpTarget?.classList.contains('welcome-help-button'))helpTarget.setAttribute('aria-expanded','false');helpTarget=null;helpPinned=false;root.querySelectorAll('.welcome-tooltip').forEach(el=>el.hidden=true);};
 function wireHelp(){
  const keys={'[data-message]':'message','[data-working]':'working','[data-owner]':'owner','[data-state]':'state','[data-copy]':'copy','[data-note-owner]':'notes','[data-note]':'notes','[data-note-save]':'notes','[data-save]':'save','[data-refresh]':'refresh','[data-download]':'download','[data-search]':'search','[data-filter]':'filter'};
  for(const [selector,key] of Object.entries(keys))root.querySelectorAll(selector).forEach(el=>el.dataset.welcomeHelp=key);
  root.querySelectorAll('[data-welcome-help]').forEach(el=>{
   if(el.dataset.helpWired)return;el.dataset.helpWired='true';
   const tip=document.createElement('span');tip.id='welcome-help-'+home+'-'+(++helpSerial);tip.className='welcome-tooltip';tip.role='tooltip';tip.hidden=true;tip.textContent=help[el.dataset.welcomeHelp];el.setAttribute('aria-describedby',tip.id);el.after(tip);
   const show=()=>{hideHelp();helpTarget=el;tip.hidden=false;const a=el.getBoundingClientRect(),b=tip.getBoundingClientRect();tip.style.left=Math.max(12,Math.min(a.left,innerWidth-b.width-12))+'px';tip.style.top=(a.bottom+b.height+12<innerHeight?a.bottom+7:Math.max(12,a.top-b.height-7))+'px';};
   el.addEventListener('pointerenter',()=>{clearTimeout(helpTimer);if(!helpPinned)show();});el.addEventListener('pointerleave',()=>{if(!helpPinned)helpTimer=setTimeout(hideHelp,160);});el.addEventListener('focus',()=>{if(!helpPinned)show();});el.addEventListener('blur',()=>{if(!helpPinned)hideHelp();});
   tip.addEventListener('pointerenter',()=>clearTimeout(helpTimer));tip.addEventListener('pointerleave',()=>{if(!helpPinned)hideHelp();});
   if(el.classList.contains('welcome-help-button'))el.onclick=()=>{if(helpPinned&&helpTarget===el){hideHelp();return;}show();helpPinned=true;el.setAttribute('aria-expanded','true');};
  });
 }
 const dismissHelp=e=>{if(e.type==='keydown'){if(e.key==='Escape')hideHelp();}else if(!e.target.closest?.('.welcome-help-button,.welcome-tooltip'))hideHelp();};
 root.addEventListener('keydown',dismissHelp);root.addEventListener('pointerdown',dismissHelp);window.addEventListener('scroll',hideHelp,true);window.addEventListener('resize',hideHelp);
 const load=async(reset=false)=>{
  if(refreshing)return;refreshing=true;status('Refreshing…');try{const result=await call('read');page=result;if(reset||!dirty){draft=page.message===oldDefault?defaultMessage:page.message;leaders=structuredClone(page.leaders);dirty=draft!==page.message;}render();status(dirty?'Welcome template ready. Save welcome settings to share it with your R4 team.':'Saved data refreshed.');}catch(e){if(!token&&!admin)login(e.message);else status(e.message,true);}finally{refreshing=false;}
 };
 function login(message=''){
  root.innerHTML='<div class="welcome-login"><div class="welcome-monogram">'+esc(tag)+'</div><p class="welcome-eyebrow">1616 · ALLIANCE WELCOME</p><h1>Welcome to '+esc(tag)+'</h1><p>Sign in to welcome your incoming players.</p><form><label>Alliance password<input type="password" name="password" autocomplete="current-password" required minlength="12" maxlength="128"></label><button class="welcome-primary" type="submit">Open alliance page</button></form><p data-status role="status"></p></div>';
  status(message,!!message);root.querySelector('form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,b=f.querySelector('button');b.disabled=true;status('Signing in…');try{const result=await call('login',{password:f.elements.password.value});token=result.token;remember();f.reset();await load(true);}catch(error){status(error.message,true);}finally{b.disabled=false;}};
 }
 function renderRows(){
  hideHelp();
  const host=root.querySelector('[data-rows]');if(!host||!page)return;
  const rows=page.players.filter(p=>(!filter||p.outreach.status===filter)&&(!query||[p.name,p.server,p.alliance,p.group,p.outreach.name].join(' ').toLowerCase().includes(query.toLowerCase())));
  root.querySelector('[data-count]').textContent=rows.length+' of '+page.players.length+' players';
  const ledgerHead='<table class="welcome-ledger" aria-label="Welcome contact roster"><colgroup><col class="welcome-col-name"><col class="welcome-col-server"><col class="welcome-col-alliance"><col class="welcome-col-hq"><col class="welcome-col-thp"><col class="welcome-col-kills"><col class="welcome-col-r4"><col class="welcome-col-status"><col class="welcome-col-action"><col class="welcome-col-action"></colgroup><thead><tr><th scope="col">Player / seat</th><th scope="col">Server</th><th scope="col">Alliance</th><th scope="col">HQ</th><th scope="col">THP</th><th scope="col">Kills</th><th scope="col">R4</th><th scope="col">Status</th><th scope="col">Copy</th><th scope="col">Notes</th></tr></thead>';
  const ledgerRows=rows.map(p=>{
   const o=p.outreach,seat=['Gold','Purple','Blue','White'].includes(p.confirmedSeat)?p.confirmedSeat:'Unknown';
   const historical=o.leaderId&&!leaders.some(l=>l.id===o.leaderId)?'<option selected value="'+esc(o.leaderId)+'">'+esc(o.name)+' (removed from R4 team)</option>':'';
   const savedDraft=noteDrafts.get(p.id)||{text:'',leaderId:o.leaderId||selected};
   return '<tbody class="welcome-player" data-player="'+esc(p.id)+'"><tr class="welcome-ledger-row"><td><span class="welcome-name-chip '+seat.toLowerCase()+'" title="'+esc(p.name)+' · '+seat+' seat · '+esc(p.group||'No group')+'">'+esc(p.name)+'<span class="welcome-sr"> · '+seat+' seat</span></span></td><td>'+esc(p.server||'—')+'</td><td>'+esc(p.alliance||'—')+'</td><td>'+esc(p.hqLevel??'—')+'</td><td>'+esc(p.power==null?'—':compact(p.power*1e6))+'</td><td>'+esc(compact(p.kills))+'</td><td><select data-owner aria-label="Contacted by · '+esc(p.name)+'">'+optionsFor(o.leaderId,'Unassigned')+historical+'</select></td><td><select data-state class="welcome-contact-state '+esc(o.status)+'" aria-label="Contact status · '+esc(p.name)+'">'+['available','claimed','completed'].map(v=>'<option value="'+v+'" '+(o.status===v?'selected':'')+'>'+v[0].toUpperCase()+v.slice(1)+'</option>').join('')+'</select></td><td><button class="welcome-icon-button" data-copy aria-label="Copy welcome for '+esc(p.name)+'" title="Copy personalized welcome"><span aria-hidden="true">⧉</span></button></td><td><button class="welcome-icon-button" data-notes-toggle aria-label="Team notes for '+esc(p.name)+'" aria-expanded="'+openNotes.has(p.id)+'" title="Team notes ('+p.notes.length+')"><span aria-hidden="true">✎</span>'+(p.notes.length?'<small>'+p.notes.length+'</small>':'')+'</button></td></tr><tr class="welcome-note-row" data-notes-panel '+(openNotes.has(p.id)?'':'hidden')+'><td colspan="10"><section class="welcome-notes"><div class="welcome-note-heading"><strong>'+esc(p.name)+' · Team notes</strong><button data-preview>Preview welcome</button></div><p class="welcome-note-help">'+esc(p.group||'No group')+' · Profession '+esc(p.profession??'—')+' · Notes are shared with the transfer team and credited to your R4 name '+helpButton('notes','team notes')+'</p><div class="welcome-note-history">'+p.notes.map(n=>'<div><strong>'+esc(n.by)+'</strong><small>'+esc(new Date(n.at).toLocaleString())+'</small><p>'+esc(n.text)+'</p></div>').join('')+'</div><label>Note by<select data-note-owner>'+optionsFor(savedDraft.leaderId)+'</select></label><label>Add a note<textarea data-note maxlength="2000" rows="2" placeholder="Saved to the player’s transfer team notes with the R4 name.">'+esc(savedDraft.text)+'</textarea></label><button data-note-save>Save team note</button><span data-note-status role="status"></span></section></td></tr><tr class="welcome-row-feedback"><td colspan="10"><p class="welcome-row-status" data-row-status role="status"></p></td></tr></tbody>';
  }).join('');
  host.innerHTML=rows.length?ledgerHead+ledgerRows+'</table>':'<p class="welcome-empty">No players match this view.</p>';
  for(const row of host.querySelectorAll('[data-player]')){
   const p=page.players.find(p=>p.id===row.dataset.player),owner=row.querySelector('[data-owner]'),state=row.querySelector('[data-state]'),rowStatus=row.querySelector('[data-row-status]');
   const change=async(leaderId,next)=>{if(busy){owner.value=p.outreach.leaderId;state.value=p.outreach.status;rowStatus.textContent='A contact is saving. Please try again in a moment.';return;}busy=true;row.querySelectorAll('button,select').forEach(el=>el.disabled=true);rowStatus.textContent='Saving contact…';try{const result=await call('contact',{playerId:p.id,leaderId,status:next,revision:p.outreach.revision});p.outreach=result.outreach;renderRows();status('Contact status saved.');}catch(e){rowStatus.textContent=e.message;owner.value=p.outreach.leaderId;state.value=p.outreach.status;}finally{busy=false;row.querySelectorAll('button,select').forEach(el=>el.disabled=false);}};
   row.querySelector('[data-notes-toggle]').onclick=e=>{const expanded=!openNotes.has(p.id);if(expanded)openNotes.add(p.id);else openNotes.delete(p.id);row.querySelector('[data-notes-panel]').hidden=!expanded;e.currentTarget.setAttribute('aria-expanded',String(expanded));};
   owner.onchange=()=>change(owner.value,owner.value?'claimed':'available');
   state.onchange=()=>{const id=owner.value||selected;if(state.value!=='available'&&!id){rowStatus.textContent='Choose an R4 in Contacted by first.';state.value=p.outreach.status;owner.focus();return;}change(id,state.value);};
   row.querySelector('[data-copy]').onclick=async e=>{if(!draft.trim()){status('Write a welcome message first.',true);return;}if(draft.includes('{r4}')&&!r4For(p)){status('Choose your R4 name under Working as before copying this welcome.',true);root.querySelector('[data-working]').focus();return;}const text=messageFor(draft,p);if(draft.length>500||text.length>500){status('This personalized welcome is '+text.length+' characters. Shorten the template so it fits within 500 characters.',true);return;}await copy(text,e.currentTarget,'⧉');};
   row.querySelector('[data-preview]').onclick=()=>{setEditor('message');root.querySelector('[data-preview-player]').value=p.id;updatePreview(p.id);root.querySelector('[data-preview-text]').scrollIntoView({behavior:'smooth',block:'center'});};
   const note=row.querySelector('[data-note]'),noteOwner=row.querySelector('[data-note-owner]');
   const keep=()=>{const old=noteDrafts.get(p.id);noteDrafts.set(p.id,{text:note.value,leaderId:noteOwner.value,id:old?.text===note.value&&old?.leaderId===noteOwner.value?old.id:crypto.randomUUID()});};note.oninput=keep;noteOwner.onchange=keep;
   row.querySelector('[data-note-save]').onclick=async e=>{keep();const d=noteDrafts.get(p.id),notice=row.querySelector('[data-note-status]');if(!d.leaderId||!d.text.trim()){notice.textContent='Choose an R4 and enter a note.';return;}const button=e.currentTarget;button.disabled=true;notice.textContent='Saving…';try{await call('note',{playerId:p.id,leaderId:d.leaderId,note:d.text,noteId:d.id});noteDrafts.delete(p.id);await load();status('Team note saved with the R4 name.');}catch(error){notice.textContent=error.message;}finally{button.disabled=false;}};
  }
  wireHelp();
 }
 function updatePreview(id){const p=page.players.find(x=>x.id===id)||page.players[0]||{name:'Player name',server:'1607',confirmedSeat:'White'};const text=messageFor(draft,p);root.querySelector('[data-preview-text]').textContent=text;const count=root.querySelector('[data-message-count]');count.textContent=draft.length+'/500 template characters · '+text.length+'/500 in this preview';count.dataset.error=String(draft.length>500||text.length>500);root.querySelector('[data-r4-preview-hint]').textContent=draft.includes('{r4}')&&!r4For(p)?'Choose Working as to fill in your R4 name. Copy is blocked until a name is available.':'R4 name: Working as, or this player’s contact owner if none is selected.';}
 function renderLeaders(){
  const list=root.querySelector('[data-leaders]');list.innerHTML=leaders.map(l=>'<span class="welcome-leader">'+esc(l.name)+'<button data-remove="'+esc(l.id)+'" aria-label="Remove '+esc(l.name)+'">×</button></span>').join('')||'<p class="welcome-muted">Add your R4 team to enable player claims and notes.</p>';
  list.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{leaders=leaders.filter(l=>l.id!==b.dataset.remove);if(selected===b.dataset.remove)selected='';dirty=true;renderLeaders();root.querySelector('[data-save]').disabled=false;});
  root.querySelector('[data-team-count]').textContent=leaders.length;
  root.querySelector('[data-working]').innerHTML=optionsFor(selected);renderRows();updatePreview(root.querySelector('[data-preview-player]').value);
 }
 function setEditor(value){editorOpen=value;root.querySelector('.welcome-settings').hidden=!value;root.querySelectorAll('[data-settings-panel]').forEach(el=>el.hidden=el.dataset.settingsPanel!==value);root.querySelectorAll('[data-editor]').forEach(el=>el.setAttribute('aria-expanded',String(el.dataset.editor===value)));hideHelp();}
 function render(){
  hideHelp();
  root.innerHTML='<header class="welcome-header welcome-sushi-header"><div class="welcome-sushi-intro"><img class="welcome-sushi-mascot" src="'+welcomeMascot+'" width="132" height="132" alt="Surfing sushi mascot"><div class="welcome-sushi-heading"><p class="welcome-eyebrow">1616 · '+esc(tag)+' WELCOME DESK</p><h1>Big welcomes.<br>Little sushi guy.</h1><p>A friendly hello for every new arrival.</p><span class="welcome-sushi-tag"><span aria-hidden="true">♡</span> A new home on 1616</span></div></div><div class="welcome-sushi-rings" aria-hidden="true"></div></header><div class="welcome-desk-toolbar"><label class="welcome-working-inline">Working as<select data-working>'+optionsFor(selected)+'</select></label><button type="button" data-editor="team" aria-expanded="false">R4 team <span data-team-count></span></button><button type="button" data-editor="message" aria-expanded="false">Edit welcome message</button><button data-copy-instructions>Copy instructions</button><details class="welcome-more"><summary>More</summary><div><button data-download>Download page</button><button data-refresh>Refresh</button>'+(!admin?'<button data-logout>Sign out</button>':'')+'</div></details></div><p data-status role="status"></p><details class="welcome-guide"><summary>How to use this Welcome desk <span>Start here · saving, claims &amp; messages</span></summary><ol>'+instructions.split('\n\n').slice(1,9).map(text=>'<li>'+esc(text.replace(/^\d+\. /,''))+'</li>').join('')+'</ol><p>'+esc(instructions.split('\n\n')[9])+'</p><p>'+esc(instructions.split('\n\n')[10])+'</p></details><section class="welcome-settings" hidden><div class="welcome-composer" data-settings-panel="message" hidden><div class="welcome-section-title"><h2>Welcome message template '+helpButton('message','welcome message and merge fields')+'</h2><span>Personalized for each player</span></div><label class="welcome-sr" for="welcome-message">Welcome message</label><textarea id="welcome-message" data-message rows="5" maxlength="500" aria-describedby="welcome-merge-guide welcome-message-count"></textarea><div class="welcome-template-tools"><button type="button" data-use-template>Use suggested template</button><span id="welcome-message-count" data-message-count aria-live="polite"></span></div><p class="welcome-hint" id="welcome-merge-guide"><strong>Merge field guide:</strong> {player} = player name · {r4} = your R4 name · {alliance} = destination alliance. Optional: {server} = source server · {seat} = seat colour.</p><div class="welcome-preview"><label>Preview for<select data-preview-player>'+page.players.map(p=>'<option value="'+esc(p.id)+'">'+esc(p.name)+'</option>').join('')+'</select></label><p data-preview-text></p><p class="welcome-hint" data-r4-preview-hint></p></div></div><div class="welcome-team" data-settings-panel="team" hidden><h2>R4 team '+helpButton('team','R4 names list')+'</h2><p class="welcome-muted">These names appear in player claims and portal team notes.</p><div data-leaders></div><form data-add-r4><label class="welcome-sr" for="r4-name">R4 name</label><input id="r4-name" name="name" placeholder="Add an R4 name" maxlength="100" required><button type="submit">Add</button></form></div><div class="welcome-settings-footer"><button class="welcome-primary" data-save '+(!dirty?'disabled':'')+'>Save welcome settings</button><span>Save message and R4 changes. Contacts and notes save separately.</span></div></section><section class="welcome-roster"><div class="welcome-roster-tools"><h2>Incoming players <small data-count></small></h2><input data-search aria-label="Search players" placeholder="Search players or groups" value="'+esc(query)+'"><select data-filter aria-label="Filter contact status"><option value="">All contacts</option>'+['available','claimed','completed'].map(v=>'<option value="'+v+'" '+(filter===v?'selected':'')+'>'+v[0].toUpperCase()+v.slice(1)+'</option>').join('')+'</select></div><div class="welcome-ledger-scroll" data-rows></div></section><footer class="welcome-footer">Approved and accepted players assigned to '+esc(tag)+'. Changes save to the 1616 portal. Downloaded pages also require internet and the alliance password.</footer>';
  root.querySelectorAll('[data-editor]').forEach(b=>b.onclick=()=>setEditor(editorOpen===b.dataset.editor?'':b.dataset.editor));setEditor(editorOpen);
  root.querySelector('[data-copy-instructions]').onclick=e=>copy(instructions,e.currentTarget,'Copy instructions');
  root.querySelector('[data-message]').value=draft;updatePreview();renderLeaders();
  root.querySelector('[data-message]').oninput=e=>{draft=e.target.value;dirty=true;root.querySelector('[data-save]').disabled=false;updatePreview(root.querySelector('[data-preview-player]').value);};
  root.querySelector('[data-use-template]').onclick=()=>{if(draft!==defaultMessage&&draft.trim()&&!confirm('Replace the current draft with the suggested welcome template? Save welcome settings to publish it.'))return;draft=defaultMessage;dirty=true;root.querySelector('[data-message]').value=draft;root.querySelector('[data-save]').disabled=false;updatePreview(root.querySelector('[data-preview-player]').value);};
  root.querySelector('[data-preview-player]').onchange=e=>updatePreview(e.target.value);
  root.querySelector('[data-search]').oninput=e=>{query=e.target.value;renderRows();};root.querySelector('[data-filter]').onchange=e=>{filter=e.target.value;renderRows();};root.querySelector('[data-working]').onchange=e=>{selected=e.target.value;renderRows();updatePreview(root.querySelector('[data-preview-player]').value);};
  root.querySelector('[data-add-r4]').onsubmit=e=>{e.preventDefault();const input=e.currentTarget.elements.name,name=input.value.trim();if(!name||leaders.some(l=>l.name.toLowerCase()===name.toLowerCase())||leaders.length>=30){status('Enter a unique R4 name. Up to 30 names are supported.',true);return;}leaders.push({id:crypto.randomUUID(),name});dirty=true;input.value='';renderLeaders();root.querySelector('[data-save]').disabled=false;};
  root.querySelector('[data-save]').onclick=async e=>{const b=e.currentTarget,sentMessage=draft,sentLeaders=structuredClone(leaders);if(draft.length>500){status('Keep the welcome template within 500 characters before saving.',true);return;}b.disabled=true;status('Saving welcome settings…');try{const result=await call('save',{message:sentMessage,leaders:sentLeaders,revision:page.revision});page.revision=result.revision;page.message=sentMessage;page.leaders=sentLeaders;dirty=draft!==sentMessage||JSON.stringify(leaders)!==JSON.stringify(sentLeaders);b.disabled=!dirty;status(dirty?'Saved. You have newer changes to save.':'Welcome message and R4 team saved.');}catch(error){status(error.message,true);b.disabled=false;}};
  root.querySelector('[data-refresh]').onclick=()=>{if(dirty&&!confirm('Reload saved settings? This replaces your unsaved welcome message and R4 changes.'))return;load(true);};
  root.querySelector('[data-logout]')?.addEventListener('click',async()=>{try{await call('logout');}finally{token='';remember();page=null;dirty=false;noteDrafts.clear();login();}});
  root.querySelector('[data-download]').onclick=async()=>{try{const css=options.css||await (await fetch(options.styleURL)).text();const config={alliance:home,endpoint:options.endpoint,key:options.key,css};const safe=JSON.stringify(config).replaceAll('<','\\u003c');const html='<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+esc(tag)+' Welcome</title><style>'+css+'</style><main id="welcome" class="welcome-app"></main><script>('+mountWelcome.toString()+')(document.getElementById("welcome"),'+safe+');<\/script></html>';const a=document.createElement('a'),url=URL.createObjectURL(new Blob([html],{type:'text/html'}));a.href=url;a.download='1616-'+tag+'-welcome.html';a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);status('Downloaded. This page uses the same database and alliance password.');}catch(e){status('Could not download the page. Please try again.',true);}};
 }
 const beforeUnload=e=>{if(dirty||[...noteDrafts.values()].some(d=>d.text.trim())){e.preventDefault();e.returnValue='';}};window.addEventListener('beforeunload',beforeUnload);
 if(admin||token)load(true);else login();
 return {isDirty:()=>dirty||[...noteDrafts.values()].some(d=>d.text.trim()),destroy:()=>{window.removeEventListener('beforeunload',beforeUnload);root.removeEventListener('keydown',dismissHelp);root.removeEventListener('pointerdown',dismissHelp);window.removeEventListener('scroll',hideHelp,true);window.removeEventListener('resize',hideHelp);root.replaceChildren();}};
}
